new:
if let aps = aps, let alert = aps["alert"] as? String {
    if let range = alert.range(of: ": ") {
        title = String(alert[..<range.lowerBound])
        body = String(alert[range.upperBound...])
    } else {
        body = alert
    }
} else if let aps = aps, let alert = aps["alert"] as? [AnyHashable: AnyObject] {
    if let alertBody = alert["body"] as? String {
        body = alertBody
        if let alertTitle = alert["title"] as? String {
            title = alertTitle
        }
    }
}
// GlowGram mod Privacy Lens: hide message text in push previews.
if ExteraPreferences.standard.value(for: ExteraSettings.privacyLensHidePushPreview), let previewBody = body, !previewBody.isEmpty {
    let languageCode = Locale.preferredLanguages.first ?? "en"
    body = languageCode.hasPrefix("ru") ? "Новое сообщение" : "New message"
}
